//! ONE executable depth probe, public market data, no trading.
use futures_util::{SinkExt,StreamExt};use serde_json::json;use spotarb_native_market_core::{parse,RawFrame,Venue};use std::time::{Duration,Instant,SystemTime,UNIX_EPOCH};use tokio_tungstenite::{connect_async,tungstenite::Message};
fn wall()->i64{SystemTime::now().duration_since(UNIX_EPOCH).unwrap().as_millis()as i64}fn v(l:&[(f64,f64)],q:f64)->Option<f64>{let(mut x,mut t)=(q,0.);for&(p,a)in l{let z=x.min(a);t+=z*p;x-=z;if x<=q*1e-9{return Some(t/q)}}None}
#[tokio::main]async fn main(){let st=Instant::now();let(mut b,_)=connect_async("wss://fstream.binance.com/stream?streams=oneusdt@bookTicker").await.unwrap();let(mut o,_)=connect_async("wss://ws.okx.com:8443/ws/v5/public").await.unwrap();o.send(Message::Text(json!({"op":"subscribe","args":[{"channel":"books5","instId":"ONE-USDT"}]}).to_string())).await.unwrap();let(mut sb,mut ob)=(None,None);while st.elapsed()<Duration::from_secs(15){tokio::select!{x=b.next()=>if let Some(Ok(Message::Text(raw)))=x{let f=RawFrame{source:None,venue:Venue::BinanceFutures,epoch:1,received_ns:st.elapsed().as_nanos()as u64,received_wall_ms:wall(),raw};if let Ok(u)=parse(&f){sb=Some(u.book)}},x=o.next()=>if let Some(Ok(Message::Text(raw)))=x{if raw.contains("\"event\""){continue}let f=RawFrame{source:None,venue:Venue::OkxSpot,epoch:1,received_ns:st.elapsed().as_nanos()as u64,received_wall_ms:wall(),raw};if let Ok(u)=parse(&f){ob=Some(u.book)}}}if sb.is_some()&&ob.is_some()&&st.elapsed()>Duration::from_secs(3){break}}
let s=ob.unwrap();let f=sb.unwrap();let ask=s.asks[0].0;let bid=f.bids[0].0;let mut out=vec![];for usd in [10.,25.,50.,100.,200.,500.]{let q=usd/ask.max(bid);let sv=v(&s.asks,q);let fv=v(&f.bids,q);out.push(match(sv,fv){(Some(a),Some(b))=>json!({"usd":usd,"qty":q,"spot_vwap":a,"future_vwap":b,"gross_bps":(b/a-1.)*10000.,"net_bps_after20":(b/a-1.)*10000.-20.,"depth":"OK"}),_=>json!({"usd":usd,"qty":q,"depth":"DENY"})})}println!("{}",json!({"one_depth":out,"spot_ask":ask,"future_bid":bid,"spot_levels":s.asks.len(),"future_levels":f.bids.len(),"trading":false}));}